using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
namespace CityForge.Editor {
[InitializeOnLoad] public static class PondTreeStudy {
const string Work="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/work/trees/", Out="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/outputs/", Root="Assets/CityForge/Art/Trees/V3EvergreenStudy/";
static double due;static int captureStep;
static PondTreeStudy(){EditorApplication.update+=Tick;}
static bool Take(string n){var p=Work+n;if(!File.Exists(p))return false;File.Delete(p);return true;}
static void Tick(){if(EditorApplication.isCompiling)return;try{if(Take("audit"))Audit();if(!EditorApplication.isPlaying&&Take("build"))Build();if(Take("capture")&&EditorApplication.isPlaying){captureStep=0;due=EditorApplication.timeSinceStartup+6;}if(due>0&&EditorApplication.timeSinceStartup>due){Capture(captureStep==0?"PondTreesSun_LakeDetail":"PondTreesSun_Zoom1",captureStep==0?40:61.955f);captureStep++;due=captureStep<2?EditorApplication.timeSinceStartup+4:0;}}catch(Exception e){due=0;File.WriteAllText(Out+"PondTrees_Error.txt",e.ToString());Debug.LogException(e);}}
static Bounds Bounds(GameObject go){var rs=go.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);return b;}
static void Audit(){var lines=new System.Collections.Generic.List<string>();foreach(var t in UnityEngine.Object.FindObjectsByType<Transform>(FindObjectsSortMode.None)){if(t.parent!=null && (t.parent.name=="Temporary shoreline reflection trees" || t.parent.name.Contains("woodland")||t.parent.name.Contains("shoreline reeds"))){var rs=t.GetComponentsInChildren<Renderer>();if(rs.Length>0)lines.Add(t.name+" | "+t.position+" height="+Bounds(t.gameObject).size.y+" prefab="+PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(t.gameObject));}}File.WriteAllLines(Out+"PondTrees_Audit.txt",lines);}
static void Place(GameObject go,Vector3 pos,float height){go.transform.localScale*=height/Bounds(go).size.y;go.transform.position=pos;var b=Bounds(go);go.transform.position+=Vector3.up*(pos.y-b.min.y);foreach(var r in go.GetComponentsInChildren<Renderer>())r.shadowCastingMode=ShadowCastingMode.TwoSided;}
[MenuItem("CityForge/Ground Study/Pond Trees and Sun")]
public static void Build(){
 var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CityForge/Art/Environment/ForestTreesTrial/medium_poly_3.prefab");var scene=EditorSceneManager.OpenScene("Assets/CityForge/Art/Environment/NaturalTerrainLab/NaturalTerrain.unity");var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);int firs=0,small=0,shore=0;
 foreach(var rootName in new[]{"MapMagic generated woodland, saplings and stones","Temporary shoreline reflection trees"}){
 var root=GameObject.Find(rootName);foreach(Transform t in root.transform.Cast<Transform>().ToArray()){
 var go=t.gameObject;if(go.GetComponentsInChildren<Renderer>().Length==0||go.name.StartsWith("Stone"))continue;var pos=t.position;bool shoreline=rootName.StartsWith("Temporary");bool fir=go.name.Contains("Fraser");float h=Bounds(go).size.y;
 if(fir){var variant=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/CityForge/Art/Environment/ForestTreesTrial/medium_poly_"+new[]{3,5,2}[firs%3]+".prefab");var replacement=(GameObject)PrefabUtility.InstantiatePrefab(variant);replacement.transform.SetParent(root.transform);replacement.transform.rotation=t.rotation;replacement.name="Mature broadleaf replacement "+firs;Place(replacement,pos,shoreline?15.5f:Mathf.Clamp(h,12,17));UnityEngine.Object.DestroyImmediate(go);firs++;}
 else if(shoreline){Place(go,pos,14+shore%3);shore++;}
 else if(h<8&&Vector2.Distance(new Vector2(pos.x,pos.z),new Vector2(133,130))<65){UnityEngine.Object.DestroyImmediate(go);small++;}
 }}
 // These sparse woody-looking cards were the temporary shoreline vegetation.
 var reeds=GameObject.Find("MapMagic pond shoreline reeds and stones");foreach(Transform t in reeds.transform.Cast<Transform>().ToArray())if(!t.name.StartsWith("Stone")){UnityEngine.Object.DestroyImmediate(t.gameObject);small++;}
 var sun=GameObject.Find("Summer sun");sun.transform.rotation=Quaternion.Euler(70,250,0);
 AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,"Assets/CityForge/Art/Environment/NaturalTerrainLab/PondTreesSun.unity");Audit();
 var meshes=prefab.GetComponentsInChildren<MeshFilter>();File.WriteAllText(Out+"PondTreesSun_Changes.txt",$"Scene: PondTreesSun.unity, derived from preserved NaturalTerrain.unity.\nReplaced {firs} Fraser firs with mature broadleaf variants (medium_poly_3, 5, 2).\nNormalized {shore} shoreline broadleaf trees to 14–16 m; shoreline replacements 15.5 m.\nRemoved {small} small shoreline vegetation/saplings.\nSun rotation: (43,222,0) -> (70,250,0), intensity/color/shadow strength unchanged.\nRepresentative broadleaf mesh triangles: {meshes.Sum(m=>m.sharedMesh.triangles.Length/3)} per instance; existing prefab LODs retained; runtime generator unchanged.\nGrass, shoreline shader, terrain geometry and Crest water configuration unchanged.\n");Debug.Log("POND TREES SUN READY");}
static void Capture(string name,float size){var c=GameObject.Find("Meadow presentation camera").GetComponent<Camera>();c.orthographicSize=size;c.transform.position=new Vector3(133,8,130)-c.transform.forward*110;c.ResetProjectionMatrix();var rt=new RenderTexture(1920,1080,24);rt.Create();var prev=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(c,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(1920,1080,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1920,1080),0,0);t.Apply();File.WriteAllBytes(Out+name+".png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
}}
